imports:
# All source files are read-only. Export writes a separate user-selected CSV file.
import csv
from contextlib import closing
import math
import sqlite3
import statistics
import zipfile
from pathlib import Path
MAX_ROWS = 5000
MAX_COLUMNS = 60

def data_text(value):
    if value is None:
        return ''
    if isinstance(value,bytes):
        return f'<binary {len(value)} bytes>'
    return str(value)[:2000]

def data_headers(values):
    result = []
    for i,value in enumerate(values):
        label = data_text(value).strip() or f'Column {i+1}'
        name = label; suffix = 2
        while name in result:
            name = f'{label} ({suffix})'; suffix += 1
        result.append(name)
    return result

def data_sqlite(path, table=None):
    # URI read-only mode and query_only prohibit modifications to the inspected database.
    with closing(sqlite3.connect(Path(path).resolve().as_uri()+'?mode=ro',uri=True,timeout=2)) as db:
        db.execute('PRAGMA query_only=ON')
        db.setlimit(sqlite3.SQLITE_LIMIT_LENGTH,1_000_000)
        db.set_progress_handler(lambda:1,2_000_000)
        tables = [r[0] for r in db.execute("SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' ORDER BY name LIMIT 101")]
        if len(tables)>100:
            raise ValueError('At most 100 tables are supported.')
        if not tables:
            raise ValueError('No data tables found.')
        table = table or tables[0]
        if table not in tables:
            raise ValueError('Select a listed table.')
        quoted = '"'+table.replace('"','""')+'"'
        cursor = db.execute('SELECT * FROM '+quoted+' LIMIT 5001')
        if len(cursor.description)>MAX_COLUMNS:
            raise ValueError('At most 60 columns are supported.')
        headers = data_headers([column[0] for column in cursor.description]); rows = []; total = 0; truncated = False
        # Stream rows so a large database cannot allocate an unbounded fetch buffer.
        for row in cursor:
            converted = [data_text(v) for v in row]
            size = sum(len(v) for v in converted)
            if len(rows) >= MAX_ROWS or total+size > 5_000_000:
                truncated = True; break
            rows.append(converted); total += size
    return headers,rows,truncated,tables

def data_load(path, table=None):
    path = Path(path); suffix = path.suffix.lower()
    if suffix in ('.db','.sqlite','.sqlite3'):
        return data_sqlite(path,table)
    if path.stat().st_size > 10*1024*1024:
        raise ValueError('CSV/XLSX files must be at most 10 MB.')
    if suffix in ('.csv','.tsv'):
        with path.open(encoding='utf-8-sig',newline='') as stream:
            sample = stream.read(8192); stream.seek(0)
            try:
                dialect = csv.Sniffer().sniff(sample,delimiters=',;\t')
            except csv.Error:
                dialect = csv.excel_tab if suffix=='.tsv' else csv.excel
            reader = csv.reader(stream,dialect); first = next(reader,None)
            if not first or len(first)>MAX_COLUMNS:
                raise ValueError('Expected a header and 1-60 columns.')
            headers = data_headers(first); rows = []
            for i,row in enumerate(reader):
                if i >= MAX_ROWS:
                    return headers,rows,True,[]
                if len(row)>MAX_COLUMNS:
                    raise ValueError('A row exceeds 60 columns.')
                rows.append([data_text(v) for v in (row+['']*len(headers))[:len(headers)]])
        return headers,rows,False,[]
    if suffix == '.xlsx':
        # Bound the expanded workbook before the optional parser reads it.
        with zipfile.ZipFile(path) as archive:
            if len(archive.infolist())>2000 or sum(i.file_size for i in archive.infolist())>50*1024*1024:
                raise ValueError('Expanded workbook is too large.')
        import openpyxl
        book = openpyxl.load_workbook(path,read_only=True,data_only=True,keep_links=False)
        try:
            sheet = book.active
            if sheet.max_column and sheet.max_column>MAX_COLUMNS:
                raise ValueError('At most 60 columns are supported.')
            iterator = sheet.iter_rows(min_row=1,max_row=MAX_ROWS+2,max_col=min(sheet.max_column or MAX_COLUMNS,MAX_COLUMNS),values_only=True)
            first = next(iterator,None)
            if not first:
                raise ValueError('Workbook has no header.')
            headers = data_headers(first); raw = []
            for row in iterator:
                raw.append([data_text(v) for v in row])
                if len(raw)>MAX_ROWS:
                    break
            return headers,raw[:MAX_ROWS],len(raw)>MAX_ROWS,[]
        finally:
            book.close()
    raise ValueError('Use CSV, TSV, XLSX or SQLite (.db/.sqlite/.sqlite3).')

def data_numeric(value):
    try:
        number = float(value)
        return number if math.isfinite(number) else None
    except (ValueError,TypeError,OverflowError):
        return None

def data_filter(rows, query, column=None, descending=False):
    query = query.casefold()
    result = [row for row in rows if not query or any(query in value.casefold() for value in row)]
    if column is not None:
        def key(row):
            value = row[column]; numeric = data_numeric(value)
            return (0,numeric) if numeric is not None else (1,value.casefold())
        result = sorted(result,key=key,reverse=descending)
    return result

def data_summary(rows,column):
    values = [n for row in rows if (n:=data_numeric(row[column])) is not None]
    return {'rows':len(rows),'numeric':len(values),'min':min(values) if values else None,'max':max(values) if values else None,'mean':statistics.mean(values) if values else None}

def data_refresh(app, reverse=None):
    if not app.headers:
        return
    if reverse is not None:
        app.descending = reverse
    selected = app.Column.get(); column = app.headers.index(selected) if selected in app.headers else 0
    app.visible = data_filter(app.rows,app.Filter.get(),column,app.descending)
    app.Grid.delete(*app.Grid.get_children())
    # Paginate the table while summaries/export use all filtered loaded rows.
    pages = max(1,(len(app.visible)+99)//100); app.page = min(max(0,app.page),pages-1)
    for row in app.visible[app.page*100:(app.page+1)*100]:
        app.Grid.insert('','end',values=row)
    stats = data_summary(app.visible,column)
    app.Summary.configure(text=f"Loaded {len(app.rows)} | Filtered {stats['rows']} | Page {app.page+1}/{pages} | Numeric {stats['numeric']} | Min {stats['min']} | Max {stats['max']} | Mean {stats['mean']}"+(' | SOURCE TRUNCATED (ROW/TEXT LIMIT)'  if app.truncated else ''))
    c = app.Chart; c.delete('all'); values = [(i,n) for i,row in enumerate(app.visible[:12]) if (n:=data_numeric(row[column])) is not None]
    scale = max([abs(n) for i,n in values]+[1]); c.create_line(10,90,940,90,fill='#74849b')
    for i,n in values:
        x = 20+i*76; y = 90-n/scale*65
        c.create_rectangle(x,min(90,y),x+45,max(90,y)+1,fill='#3975c6',outline='')
        c.create_text(x+22,170,text=str(i+1)); c.create_text(x+22,y-8 if n>=0 else y+8,text=f'{n:.3g}')
    c.create_text(480,195,text=f'{selected}: first 12 filtered rows; zero baseline')

def data_open(app, table_change=False):
    path = app.source if table_change else filedialog.askopenfilename(parent=app.Form1,filetypes=[('Data','*.csv *.tsv *.xlsx *.db *.sqlite *.sqlite3')])
    if not path:
        return
    try:
        headers,rows,truncated,tables = data_load(path,app.Table.get() if table_change else None)
        app.headers = headers; app.rows = rows; app.truncated = truncated; app.source = path; app.page = 0
        app.Table.configure(values=tables,state='readonly' if tables else 'disabled')
        if tables and not table_change:
            app.Table.set(tables[0])
        if not tables:
            app.Table.set('')
        app.Column.configure(values=headers); app.Column.set(headers[0]); app.Grid.configure(columns=[f'c{i}' for i in range(len(headers))],show='headings')
        for i,label in enumerate(headers):
            app.Grid.heading(f'c{i}',text=label); app.Grid.column(f'c{i}',width=140,minwidth=80,stretch=False)
        data_refresh(app)
    except Exception as exc:
        messagebox.showerror('Data Explorer',str(exc),parent=app.Form1)

def data_page(app, delta):
    app.page += delta; data_refresh(app)

def data_export(app):
    path = filedialog.asksaveasfilename(parent=app.Form1,defaultextension='.csv',filetypes=[('CSV','*.csv')])
    if not path:
        return
    try:
        if app.source and (Path(path).resolve()==Path(app.source).resolve() or Path(path).exists() and Path(path).samefile(app.source)):
            raise ValueError('Choose a separate export file; source data is read-only.')
        with open(path,'w',encoding='utf-8',newline='') as stream:
            writer = csv.writer(stream); writer.writerow(app.headers)
            # Escape formula prefixes for safe spreadsheet opening; source data is unchanged.
            writer.writerows([["'"+v if v.lstrip().startswith(('=','+','-','@')) and data_numeric(v) is None else v for v in row] for row in app.visible])
    except (OSError,ValueError) as exc:
        messagebox.showerror('Data Explorer',str(exc),parent=app.Form1)
